CREATE OR REPLACE FUNCTION private.dog_name_accusative(p_name text, p_sex text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_name text := pg_catalog.btrim(coalesce(p_name,'')); 
begin
 if v_name='' then return 'psíka'; end if;
 if p_sex='female' and pg_catalog.lower(pg_catalog.right(v_name,1))='a' and char_length(v_name)>1 then
   return pg_catalog.left(v_name,char_length(v_name)-1) ||
     case when pg_catalog.right(v_name,1)='A' then 'U' else 'u' end;
 end if;
 return v_name;
end
$function$
